import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {4, 0, 5, 0, 0, 6};
        int pos = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] != 0) {
                int temp = a[pos];
                a[pos] = a[i];
                a[i] = temp;
                pos++;
            }
        }
        System.out.println(Arrays.toString(a));
    }
}
